import time


class HourlyPricing:
    DEFAULT_RATES = {"motorcycle": 100, "car": 200, "truck": 500}

    def __init__(self, rates=None):
        self.rates = dict(self.DEFAULT_RATES if rates is None else rates)

    def fee(self, kind, minutes):
